const tree = $input.first().json.tree || [];
// Get all markdown files in 01-inbox/
const inboxFiles = tree
  .filter(item => item.type === 'blob' && item.path.startsWith('01-inbox/') && item.path.endsWith('.md'))
  .map(item => ({ json: { filepath: item.path, sha: item.sha } }));

console.log(`[brain-inbox-retry] Found ${inboxFiles.length} files in inbox`);
return inboxFiles;

const fileData = $input.first().json;
const filepath = fileData.path;
const sha = fileData.sha;

// Decode base64 content
const raw = Buffer.from(fileData.content, 'base64').toString('utf8');

// Check if status: unprocessed is in frontmatter
if (!raw.includes('status: unprocessed')) {
  // Already processed or no status field — skip
  return [];
}

// Extract fields from frontmatter for Gemini prompt
const frontmatterMatch = raw.match(/^---([\s\S]*?)---/);
const frontmatter = frontmatterMatch ? frontmatterMatch[1] : '';

const titleMatch = frontmatter.match(/title:\s*"?([^"\n]+)"?/);
const sourceMatch = frontmatter.match(/source:\s*(.+)/);
const createdMatch = frontmatter.match(/created:\s*(.+)/);

const title = titleMatch ? titleMatch[1].trim() : 'Untitled';
const source = sourceMatch ? sourceMatch[1].trim() : 'chatgpt';
const created = createdMatch ? createdMatch[1].trim().slice(0, 10) : new Date().toISOString().slice(0, 10);

// Check age — only retry files older than 1 hour
const createdMs = new Date(created).getTime();
const ageMs = Date.now() - createdMs;
if (ageMs < 3600000) {
  console.log(`[brain-inbox-retry] ${filepath} is less than 1 hour old — skipping`);
  return [];
}

// Extract body content (after frontmatter)
const bodyAfterFrontmatter = raw.replace(/^---[\s\S]*?---/, '').trim();

// Build Gemini prompt
const promptText = [
  'You are processing a captured note for a personal knowledge management system using the PARA method.',
  '\n\nPARA definitions:',
  '\n- project: has a clear finish line (SaaS app, automation, specific deliverable)',
  '\n- area: ongoing responsibility, no end date (health, finance, business, personal development, ministry)',
  '\n- resource: reference material, research, learning, frameworks, how-to knowledge',
  '\n- inbox: unclear, mixed, needs more context',
  '\n\nContext about the owner:',
  '\n- Builds SaaS apps and business automations',
  '\n- Manages prochattools business (statuslink, xgrow, prochat, says-the-bible, probot)',
  '\n- Has Yeshua Academy (ministry work)',
  '\n- Goal: automate everything, optimise costs, work efficiently',
  `\n\nTitle hint: ${title}`,
  `\n\nContent to classify:\n${bodyAfterFrontmatter}`,
  '\n\nRespond ONLY with valid JSON (no markdown fences, no extra text):\n{\n  "title": "concise title max 6 words",\n  "para_type": "project|area|resource|inbox",\n  "confidence": 0.0,\n  "area_hint": "which life or business area",\n  "tags": ["tag1", "tag2"],\n  "summary": "2-3 sentence summary of the key insight or decision",\n  "key_points": ["point 1", "point 2", "point 3"],\n  "action_items": ["actionable task if any"],\n  "note_content": "full structured markdown body for the note, without frontmatter"\n}'
].join('');

const geminiBody = JSON.stringify({
  contents: [{ parts: [{ text: promptText }] }]
});

console.log(`[brain-inbox-retry] Retrying classification for ${filepath}`);

return [{
  json: {
    filepath,
    sha,
    title,
    source,
    date: created,
    geminiBody
  }
}];

const fileData = $('Check If Unprocessed').first().json;
console.log(`[brain-inbox-retry] Gemini still failing for ${fileData.filepath} — will retry tomorrow`);
return [];

const geminiResponse = $input.first().json;
const fileData = $('Check If Unprocessed').first().json;

const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!rawText) { return []; }

const stripped = rawText
  .replace(/^```json\s*/m, '')
  .replace(/^```\s*/m, '')
  .replace(/\s*```$/m, '')
  .trim();

function sanitizeJsonString(str) {
  let result = '';
  let inString = false;
  let escaped = false;
  for (let i = 0; i < str.length; i++) {
    const c = str[i];
    if (escaped) { result += c; escaped = false; }
    else if (c === '\\' && inString) { result += c; escaped = true; }
    else if (c === '"') { result += c; inString = !inString; }
    else if (inString && c === '\n') { result += '\\n'; }
    else if (inString && c === '\r') { result += '\\r'; }
    else if (inString && c === '\t') { result += '\\t'; }
    else if (inString && c.charCodeAt(0) < 32) {
      result += '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0');
    } else { result += c; }
  }
  return result;
}

let parsed;
try {
  parsed = JSON.parse(sanitizeJsonString(stripped));
} catch (e) {
  console.log(`[brain-inbox-retry] JSON parse failed for ${fileData.filepath}: ${e.message}`);
  return [];
}

const date = fileData.date;
const source = fileData.source;

const tagsYaml = (parsed.tags || ['capture'])
  .map(t => `  - ${t}`).join('\n');

const frontmatter = [
  '---',
  'type: capture',
  `source: ${source}`,
  `title: "${parsed.title || fileData.title}"`,
  `para_type: ${parsed.para_type || 'inbox'}`,
  `confidence: ${parsed.confidence ?? 0}`,
  `area: ${parsed.area_hint || ''}`,
  `created: ${date}`,
  'status: processed',
  'tags:',
  tagsYaml,
  '---'
].join('\n');

const keyPoints = (parsed.key_points || []).map(p => `- ${p}`).join('\n') || '-';
const actionItems = (parsed.action_items || []).map(a => `- [ ] ${a}`).join('\n');
const confidence = Math.round((parsed.confidence ?? 0) * 100);

const noteBody = [
  frontmatter,
  '',
  `# ${parsed.title || fileData.title}`,
  '',
  '## Summary',
  parsed.summary || '',
  '',
  '## Key Points',
  keyPoints,
  '',
  actionItems ? `## Action Items\n${actionItems}\n` : '',
  '## Notes',
  parsed.note_content || '',
  '',
  '---',
  `*${source} capture · ${date} · ${confidence}% confidence · suggested: ${parsed.para_type}*`,
  `*Classified by retry job · Review in [[home|Command Center]]*`
].join('\n');

return [{
  json: {
    filepath: fileData.filepath,
    sha: fileData.sha,
    classifiedContent: noteBody,
    title: parsed.title || fileData.title,
    para_type: parsed.para_type,
    confidence: parsed.confidence
  }
}];

const classified = $input.first().json;
const sha = classified.sha;
if (!sha) {
  throw new Error(`SHA missing for ${classified.filepath}`);
}
const contentBase64 = Buffer.from(classified.classifiedContent, 'utf8').toString('base64');
return [{
  json: {
    filepath: classified.filepath,
    title: classified.title,
    para_type: classified.para_type,
    putBody: JSON.stringify({
      message: `brain: classified (retry) — ${classified.title} (${classified.para_type})`,
      content: contentBase64,
      sha
    })
  }
}];
